use primal_net::{
    Channel, ClientTransport, ConnectionId, ServerEvent, ServerTransport, TransportError,
};
use std::{
    collections::VecDeque,
    io,
    net::{SocketAddr, UdpSocket},
    time::Duration,
};

fn local() -> SocketAddr {
    "127.0.0.1:0".parse().unwrap()
}

/// Only forwards genuine packets generated by the two test endpoints. No packet mutation.
struct Relay {
    socket: UdpSocket,
    server: SocketAddr,
    client: Option<SocketAddr>,
    pending: VecDeque<(usize, SocketAddr, Vec<u8>)>,
    observed_packets: usize,
    observed_bytes: usize,
    dropped: usize,
}
impl Relay {
    fn new(server: SocketAddr) -> Self {
        let socket = UdpSocket::bind(local()).unwrap();
        socket.set_nonblocking(true).unwrap();
        Self {
            socket,
            server,
            client: None,
            pending: VecDeque::new(),
            observed_packets: 0,
            observed_bytes: 0,
            dropped: 0,
        }
    }
    fn pump(&mut self, tick: usize) {
        let mut buf = [0u8; 2048];
        loop {
            let (n, from) = match self.socket.recv_from(&mut buf) {
                Ok(packet) => packet,
                Err(e) if e.kind() == io::ErrorKind::WouldBlock => break,
                Err(e) => panic!("relay receive: {e}"),
            };
            self.observed_packets += 1;
            self.observed_bytes += n;
            let to = if from == self.server {
                self.client.unwrap()
            } else {
                self.client = Some(from);
                self.server
            };
            // Deterministic loss of one packet out of seven, 30 ms one-way latency.
            if self.observed_packets.is_multiple_of(7) {
                self.dropped += 1;
                continue;
            }
            assert!(self.pending.len() < 1024);
            self.pending.push_back((tick + 3, to, buf[..n].to_vec()));
        }
        while self.pending.front().is_some_and(|p| p.0 <= tick) {
            let (_, to, packet) = self.pending.pop_front().unwrap();
            assert_eq!(self.socket.send_to(&packet, to).unwrap(), packet.len());
        }
    }
}

#[test]
fn genuine_udp_with_delay_and_loss_keeps_reliable_order_and_fragmented_chunks() {
    let mut server = ServerTransport::bind(local(), 4).unwrap();
    let mut relay = Relay::new(server.local_addr());
    let id = ConnectionId(73421);
    let mut client =
        ClientTransport::connect(local(), relay.socket.local_addr().unwrap(), id).unwrap();
    let mut sent = false;
    let mut reliable = Vec::new();
    let mut chunk = None;
    let mut inputs = 0;
    let mut snapshots = 0;
    let mut connected = false;
    let chunk_bytes = vec![91; 16384];
    let dt = Duration::from_millis(10);
    for tick in 0..3000 {
        client.poll(dt).unwrap();
        if client.is_connected() && !sent {
            for seq in 0u8..32 {
                client.send(Channel::Control, vec![seq]).unwrap();
            }
            server
                .send(id, Channel::Chunks, chunk_bytes.clone())
                .unwrap();
            sent = true;
        }
        if sent && tick < 600 {
            client.send(Channel::Input, vec![1; 40]).unwrap();
            server.send(id, Channel::Snapshots, vec![2; 80]).unwrap();
        }
        client.flush().unwrap();
        relay.pump(tick);
        server.poll(dt).unwrap();
        while let Some(event) = server.next_event() {
            if event == ServerEvent::Connected(id) {
                connected = true;
            }
        }
        while let Some((from, channel, payload)) = server.recv() {
            assert_eq!(from, id);
            match channel {
                Channel::Control => reliable.push(payload[0]),
                Channel::Input => inputs += 1,
                _ => panic!("unexpected uplink"),
            }
        }
        server.flush().unwrap();
        relay.pump(tick);
        while let Some((channel, payload)) = client.recv() {
            match channel {
                Channel::Chunks => chunk = Some(payload),
                Channel::Snapshots => snapshots += 1,
                _ => panic!("unexpected downlink"),
            }
        }
        if tick > 600 && reliable.len() == 32 && chunk.is_some() {
            break;
        }
        std::thread::yield_now();
    }
    assert!(connected && sent);
    assert_eq!(reliable, (0u8..32).collect::<Vec<_>>());
    assert_eq!(chunk, Some(chunk_bytes));
    assert!(inputs > 0 && snapshots > 0);
    assert!(relay.dropped > 0 && relay.observed_bytes > 16384 && relay.observed_packets > 32);
    assert!(client.rtt() > Duration::ZERO);
    assert_eq!(server.stats().received_bytes, 32 + inputs * 40);
    eprintln!(
        "UDP relay: {} packets, {} bytes, {} dropped; RTT {:?}",
        relay.observed_packets,
        relay.observed_bytes,
        relay.dropped,
        client.rtt()
    );
}

#[test]
fn bounded_send_returns_backpressure_without_disconnect() {
    let mut server = ServerTransport::bind(local(), 1).unwrap();
    let id = ConnectionId(971);
    let mut client = ClientTransport::connect(local(), server.local_addr(), id).unwrap();
    for _ in 0..100 {
        let dt = Duration::from_millis(20);
        client.poll(dt).unwrap();
        client.flush().unwrap();
        server.poll(dt).unwrap();
        server.flush().unwrap();
        while server.next_event().is_some() {}
        if client.is_connected() {
            break;
        }
    }
    assert!(client.is_connected());
    let mut accepted = 0;
    loop {
        match client.send(Channel::Control, vec![42; 64 * 1024]) {
            Ok(()) => accepted += 1,
            Err(TransportError::QueueFull(Channel::Control)) => break,
            other => panic!("unexpected send {other:?}"),
        }
        assert!(accepted <= 32);
    }
    assert!(client.is_connected());
    assert_eq!(client.stats().backpressure_events, 1);
    assert!(matches!(
        client.send(Channel::Input, vec![0; 1101]),
        Err(TransportError::MessageTooLarge { .. })
    ));
    assert!(matches!(
        server.send(ConnectionId(9999), Channel::Control, vec![1]),
        Err(TransportError::NotConnected)
    ));
}
